# Chandra's Embercat: "{T}: Add {R}. Spend this mana only to cast an Elemental spell or a Chandra
# planeswalker spell."  Vodalian Arcanist's layout: the compiled mana ability, then a THIS_MANA
# MANA_POLICY static. "an Elemental spell" is a bare SUBTYPE_EQ (Windrider Wizard's "Wizard
# spell"); "a Chandra planeswalker" is Keral Keep Disciples' SUBTYPE_EQ Chandra + TYPE_EQ
# Planeswalker.
policy = StaticAbility(
    effect=A(Verb.MANA_POLICY, {
        'filter': FOr(
            children=(
                FAtom(pred=FAtomPred.SUBTYPE_EQ, string_value='Elemental'),
                FAnd(
                    children=(
                        FAtom(pred=FAtomPred.SUBTYPE_EQ, string_value='Chandra'),
                        FAtom(pred=FAtomPred.TYPE_EQ, string_value='Planeswalker'),
                    ),
                ),
            ),
        ),
        'scope': 'THIS_MANA',
    }),
)
abilities = [compiled[0], policy, compiled[1]]
